mapper.select:
SELECT E.DOMAIN_ID , C.COMPANY_NM , E.COMPANY_CD , E.EMAIL , E.EMP_NM , SF_GET_CODE_NM('ko-KR', '03000', E.POS_CD, E.COMPANY_CD, E.DOMAIN_ID) AS POS_NM , D.DEPT_NM FROM EMP_MASTER E INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID) INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID)
E.DOMAIN_ID = #{domainId} AND E.COMPANY_CD = #{companyCd} AND E.EMAIL != #{email} AND (E.HIDDEN_YN != 'Y' OR E.HIDDEN_YN IS NULL)
AND D.DEPT_CD = #{deptCd}
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
ORDER BY DEPT_ORD, DEPT_NM, EMP_NM
LIMIT #{start}, #{length}

SELECT 
	COUNT(*)
FROM EMP_MASTER E
	INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID)
	INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID)

	E.DOMAIN_ID = #{domainId}
	AND E.COMPANY_CD = #{companyCd}
	AND E.EMAIL != #{email}
	AND (E.HIDDEN_YN != 'Y' OR E.HIDDEN_YN IS NULL)

		AND D.DEPT_CD = #{deptCd}


		AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')


ORDER BY DEPT_ORD, DEPT_NM, EMP_NM

SELECT C.COMPANY_NM , E.DOMAIN_ID , E.COMPANY_CD , E.EMAIL , E.EMP_NM , SF_GET_CODE_NM('ko-KR', '03000', E.POS_CD, E.COMPANY_CD, E.DOMAIN_ID) AS POS_NM , D.DEPT_NM FROM EMP_MASTER E INNER JOIN DEPT_MASTER D ON (E.DEPT_CD = D.DEPT_CD AND E.COMPANY_CD = D.COMPANY_CD AND E.DOMAIN_ID = D.DOMAIN_ID) INNER JOIN COMPANY_MASTER C ON (E.COMPANY_CD = C.COMPANY_CD AND E.DOMAIN_ID = C.DOMAIN_ID)
E.DOMAIN_ID = #{domainId} AND E.COMPANY_CD = #{companyCd} AND (E.HIDDEN_YN != 'Y' OR E.HIDDEN_YN IS NULL)
AND D.DEPT_CD = #{deptCd}
AND E.EMP_NM LIKE REPLACE(CONCAT('%', #{empNm}, '%'), ' ','')
ORDER BY DEPT_ORD, DEPT_NM, EMP_NM
LIMIT #{start}, #{length}
